    instruction: I.cloze,
    passage:
      '내일은 기다리던 여행을 떠나요. 생각만 해도 마음이 ___요. 그런데 첫 해외여행이라 조금 긴장돼서 가슴도 ___어요. 친구가 같이 간다고 해서 다시 ___이 나요.',
